SELECT CASE WHEN budget >= 3230000 THEN 'high' WHEN budget >= 946000 THEN 'mid' ELSE 'low' END AS budget_bucket, location, dept_name, COUNT(CASE WHEN location = 'Tokyo' THEN 1 END) AS tokyo_count, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list FROM departments WHERE location NOT IN ('New York', 'Chiang Mai') AND budget BETWEEN 2069000 AND 3095000 GROUP BY CASE WHEN budget >= 3230000 THEN 'high' WHEN budget >= 946000 THEN 'mid' ELSE 'low' END, location, dept_name HAVING COUNT(CASE WHEN location = 'Tokyo' THEN 1 END) >= 5
